/** A dict entry's label (what exports write for a dict column). */
async function dictLabel(code: string, value: string, lang = 'zh-CN') {
  const [row] = await ds.query(
    'SELECT label, label_i18n AS labels FROM cfg_dict_entry WHERE dict_code = ? AND value = ?',
    [code, value],
  )
  return row?.labels?.[lang] ?? row?.label ?? value
}

async function user(name: string, roles: number[], deptId: number | null = null) {
  const id = await insertRow(ds.manager, 'iam_user', {
    username: PREFIX + name,
    display_name: name,
    password_hash: 'not-used-by-this-spec',
    password_changed_at: new Date(),
    dept_id: deptId,
  })
  for (const r of roles)
    await ds.query('INSERT INTO iam_user_roles (user_id, role_id) VALUES (?, ?)', [id, r])
  userIds.push(id)
  return (await signIn(app, PREFIX + name)).accessToken
}

beforeAll(async () => {
  const moduleRef = await Test.createTestingModule({ imports: [AppModule] }).compile()
  app = setupApp(moduleRef.createNestApplication<NestExpressApplication>({ logger: false }))
  await app.listen(0, '127.0.0.1')
  ds = app.get<DataSource>(getDataSourceToken())
  redis = app.get(REDIS)
  i18n = app.get(I18nService)
  await cleanRedis(redis)
  lastId = Number((await ds.query('SELECT COALESCE(MAX(id), 0) AS n FROM demo_book'))[0].n)
  roleId = await insertRow(ds.manager, 'iam_role', {
    code: `${PREFIX}reader`,
    name: `${PREFIX}reader`,
    data_scope: 'all',
  })
  const browse = await findId(ds.manager, 'iam_menu', { perms: bookPerms.browse })
  await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [roleId, browse])
  tokens.admin = (await signIn(app)).accessToken
  tokens.reader = await user('reader', [roleId])
  tokens.plain = await user('plain', [])
  // two top-level depts of this spec (tree_path is their own id); the operator sits in `mine`
  for (const k of ['mine', 'other'] as const) {
    DEPT[k] = await insertRow(ds.manager, 'iam_dept', { tree_path: '/', name: `${PREFIX}${k}` })
    await ds.query('UPDATE iam_dept SET tree_path = ? WHERE id = ?', [`/${DEPT[k]}/`, DEPT[k]])
  }
  ownRoleId = await insertRow(ds.manager, 'iam_role', {
    code: `${PREFIX}own`,
    name: `${PREFIX}own`,
    data_scope: 'own_dept',
  })
  for (const perms of Object.values(bookPerms))
    await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [
      ownRoleId,
      await findId(ds.manager, 'iam_menu', { perms }),
    ])
  tokens.own = await user('own', [ownRoleId], DEPT.mine)
})

afterAll(async () => {
  if (ds) {
    await ds.query('DELETE FROM demo_book WHERE id > ?', [lastId])
    if (userIds.length) {
      await ds.query('DELETE FROM iam_user_roles WHERE user_id IN (?)', [userIds])
      await ds.query('DELETE FROM iam_user WHERE id IN (?)', [userIds])
    }
    await ds.query('DELETE FROM iam_role_menus WHERE role_id IN (?)', [[roleId, ownRoleId]])
    await ds.query('DELETE FROM iam_role WHERE id IN (?)', [[roleId, ownRoleId]])
    await ds.query('DELETE FROM iam_dept WHERE id IN (?)', [Object.values(DEPT)])
  }
  if (redis) await cleanRedis(redis)
  await app?.close()
})

describe('CRUD', () => {
  it('create → 201 with the row (defaults filled, audit columns set); get returns it', async () => {
    const tag = unique()
    const res = await create(body(tag)).expect(201)
    const row = res.body.data
    expect(row).toMatchObject({
      id: expect.any(Number),
      ...body(tag),
      author: null,
      coverUrl: null,
      deptId: null,
      enabled: true,
      createdBy: expect.any(Number),
    })
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt)
    const got = await call('admin', 'get', `/${row.id}`).expect(200)
    expect(got.body.data).toEqual(row)
  })

  it('list: newest first by the sort whitelist, all live rows counted, paging, enabled equals, created_at range', async () => {
    const ids: number[] = []
    for (let i = 0; i < 3; i++) ids.push((await add(body(unique()))).id)
    const list = (query: object) => call('admin', 'get').query(query).expect(200)
    const res = await list({ sort: '-id', pageSize: 3 })
    expect(idsOf(res)).toEqual([...ids].reverse())
    expect(res.body.data.total).toBe(await count())
    expect(idsOf(await list({ sort: '-id', page: 2, pageSize: 2 }))[0]).toBe(ids[0])
    const off = (await add(body(unique(), { enabled: false }))).id
    expect(idsOf(await list({ enabled: 'false', sort: '-id', pageSize: 1 }))).toEqual([off])
    expect(idsOf(await list({ enabled: 'true', sort: '-id', pageSize: 1 }))).toEqual([ids[2]])
    // created_at from / to: instants (ISO-8601 with an offset)
    const [{ at }] = await ds.query('SELECT created_at AS at FROM demo_book WHERE id = ?', [ids[0]])
    const around = (ms: number) => new Date(at.getTime() + ms).toISOString()
    expect(
      idsOf(await list({ createdAtFrom: around(-1000), createdAtTo: around(1000), sort: '-id' })),
    ).toContain(ids[0])
    expect(idsOf(await list({ createdAtTo: around(-1000), sort: '-id' }))).not.toContain(ids[0])
  })

  it('list: text filters contain (LIKE wildcards literal) and combine with enabled', async () => {
    const tag = unique()
    for (const suffix of ['a', 'b', 'c']) await add(body(`${tag}-${suffix}`))
    await add(body(`${tag}-off`, { enabled: false }))
    await add(body(`${tag}_x`))

    const list = (query: object) => call('admin', 'get').query(query).expect(200)
    const keys = (res: request.Response) => res.body.data.items.map((r: { isbn: string }) => r.isbn)
    const res = await list({ isbn: `${tag}-`, enabled: 'true', sort: '-id' })
    expect(keys(res)).toEqual([`${tag}-c`, `${tag}-b`, `${tag}-a`])
    expect(res.body.data.total).toBe(3)
    expect(keys(await list({ isbn: tag, enabled: 'false' }))).toEqual([`${tag}-off`])
    // `%` and `_` in the filter are plain characters
    expect(keys(await list({ isbn: `${tag}_` }))).toEqual([`${tag}_x`])
    expect(keys(await list({ title: `${tag}-b title` }))).toEqual([`${tag}-b`])
    // a date range includes both ends
    expect(
      keys(
        await list({
          isbn: `${tag}-a`,
          publishedOnFrom: '2024-05-01',
          publishedOnTo: '2024-05-01',
        }),
      ),
    ).toEqual([`${tag}-a`])
    expect(keys(await list({ isbn: `${tag}-a`, publishedOnTo: '1970-01-01' }))).toEqual([])
    const page2 = await list({ isbn: `${tag}-`, sort: 'id', page: 2, pageSize: 2 })
    expect(keys(page2)).toEqual([`${tag}-c`, `${tag}-off`])
    expect(page2.body.data.total).toBe(4)
  })

  it('update changes the fields sent and keeps the others; enabled toggles', async () => {
    const tag = unique()
    const { id } = await add(body(tag))
    await call('admin', 'put', `/${id}`, { title: `${tag} renamed` }).expect(200)
    await call('admin', 'put', `/${id}/enabled`, { enabled: false }).expect(200)
    expect((await call('admin', 'get', `/${id}`)).body.data).toMatchObject({
      ...body(tag),
      title: `${tag} renamed`,
      enabled: false,
    })
  })

  it('a row PUT back as loaded (nulls included, as the edit form sends it) → 200, unchanged', async () => {
    const row = await add(body(unique()))
    const loaded = Object.fromEntries(FORM.map((f) => [f, row[f]]))
    await call('admin', 'put', `/${row.id}`, loaded).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data).toMatchObject(loaded)
  })

  it('delete and batch delete (soft: the rows stay, marked deleted)', async () => {
    const ids: number[] = []
    for (let i = 0; i < 3; i++) ids.push((await add(body(unique()))).id)
    await call('admin', 'delete', `/${ids[0]}`).expect(200)
    await call('admin', 'post', '/batch-delete', { ids: ids.slice(1) }).expect(200)
    expect(
      await ds.query('SELECT id FROM demo_book WHERE id IN (?) AND deleted_at IS NULL', [ids]),
    ).toEqual([])
    expect(await ds.query('SELECT id FROM demo_book WHERE id IN (?)', [ids])).toHaveLength(3)
    await call('admin', 'get', `/${ids[0]}`).expect(404)
    // unique among live rows only: a deleted row's isbn can be used again
    const { isbn } = (
      await ds.query('SELECT isbn AS isbn FROM demo_book WHERE id = ?', [ids[0]])
    )[0]
    await create({ ...body(unique()), isbn }).expect(201)
  })
})

describe('errors', () => {
  it('403 per permission: browse-only may list, not view/create/modify/delete; no perm → no list', async () => {
    const { id } = await add(body(unique()))
    await call('reader', 'get').expect(200)
    const forbidden = [
      call('reader', 'get', `/${id}`),
      call('reader', 'post', '', body(unique())),
      call('reader', 'put', `/${id}`, {}),
      call('reader', 'put', `/${id}/enabled`, { enabled: false }),
      call('reader', 'delete', `/${id}`),
      call('reader', 'post', '/batch-delete', { ids: [id] }),
      call('plain', 'get'),
    ]
    for (const res of await Promise.all(forbidden)) {
      expect(res.status).toBe(403)
      expect(res.body.code).toBe(Err.FORBIDDEN.code)
    }
  })

  it('400: invalid body / query / id, with translated field messages', async () => {
    const { id } = await add(body(unique()))
    const required = (lang: string, field: string) =>
      t(lang, 'validation.required', { field: label(lang, field) })
    expect(label('zh-CN', 'isbn')).not.toMatch(/^field\./)
    expect(label('en-US', 'isbn')).not.toMatch(/^field\./)
    const zh = await create({ ...body(unique()), isbn: '', title: 'x'.repeat(201) }).expect(400)
    expect(zh.body).toMatchObject({
      code: Err.VALIDATION_FAILED.code,
      msg: required('zh-CN', 'isbn'),
    })
    expect(zh.body.errors).toEqual([
      { path: 'isbn', msg: required('zh-CN', 'isbn') },
      {
        path: 'title',
        msg: t('zh-CN', 'validation.too_big.string', {
          field: label('zh-CN', 'title'),
          maximum: 200,
        }),
      },
    ])
    const { isbn: _, ...keyless } = body(unique())
    const en = await create(keyless).set('Accept-Language', 'en-US').expect(400)
    expect(en.body.errors).toEqual([{ path: 'isbn', msg: required('en-US', 'isbn') }])
    await call('admin', 'get').query({ sort: 'coverUrl' }).expect(400)
    await call('admin', 'put', `/${id}/enabled`, { enabled: 'no' }).expect(400)
    await call('admin', 'post', '/batch-delete', { ids: [] }).expect(400)
    await call('admin', 'get', '/abc').expect(400)
  })

  it('409 duplicate: a unique value already taken (create and update; case-insensitive)', async () => {
    const tag = unique()
    const taken = await add(body(tag))
    const other = await add(body(unique()))
    for (const res of [
      await create({ ...body(unique()), isbn: taken.isbn.toUpperCase() }),
      await call('admin', 'put', `/${taken.id}`, { isbn: other.isbn }),
    ]) {
      expect(res.status).toBe(409)
      expect(res.body).toMatchObject({
        code: Err.DUPLICATE.code,
        msg: t('zh-CN', Err.DUPLICATE.key),
      })
    }
  })

  it('404: unknown ids for get, update, enabled, delete; a batch with one unknown id deletes nothing', async () => {
    const { id } = await add(body(unique()))
    for (const res of [
      await call('admin', 'get', `/${MISSING}`),
      await call('admin', 'put', `/${MISSING}`, {}),
      await call('admin', 'put', `/${MISSING}/enabled`, { enabled: true }),
      await call('admin', 'delete', `/${MISSING}`),
      await call('admin', 'post', '/batch-delete', { ids: [id, MISSING] }),
    ]) {
      expect(res.status).toBe(404)
      expect(res.body.code).toBe(Err.NOT_FOUND.code)
    }
    await call('admin', 'get', `/${id}`).expect(200)
  })

  it('the same create submitted twice within 3 s → 429 (@Idempotent)', async () => {
    const tag = unique()
    await create(body(tag)).expect(201)
    const again = await create(body(tag)).expect(429)
    expect(again.body.code).toBe(Err.TOO_MANY_REQUESTS.code)
  })
})

describe('data scope (see docs/design-notes.md#data-scope): an own_dept operator', () => {
  const denied = (res: request.Response) => {
    expect(res.status).toBe(404)
    expect(res.body.code).toBe(Err.NOT_FOUND.code)
  }

  it('list and get leave out rows of another dept; update, enabled, delete and batch delete of one → 404, nothing written', async () => {
    const mine = await addIn(DEPT.mine)
    const other = await addIn(DEPT.other)
    const listed = idsOf(await call('own', 'get').query({ sort: '-id', pageSize: 100 }).expect(200))
    expect(listed).toContain(mine.id)
    expect(listed).not.toContain(other.id)
    denied(await call('own', 'get', `/${other.id}`))
    denied(await call('own', 'put', `/${other.id}`, {}))
    denied(await call('own', 'put', `/${other.id}/enabled`, { enabled: false }))
    denied(await call('own', 'delete', `/${other.id}`))
    // one id out of scope: the whole batch is refused
    denied(await call('own', 'post', '/batch-delete', { ids: [mine.id, other.id] }))
    expect((await call('admin', 'get', `/${other.id}`).expect(200)).body.data).toEqual(other)
    await call('own', 'get', `/${mine.id}`).expect(200)
  })

  it('create / update into another dept → 404, nothing written; into its own → 201', async () => {
    const before = await count()
    denied(await call('own', 'post', '', body(unique(), { deptId: DEPT.other })))
    expect(await count()).toBe(before)
    const mine = (await call('own', 'post', '', body(unique(), { deptId: DEPT.mine })).expect(201))
      .body.data
    denied(await call('own', 'put', `/${mine.id}`, { deptId: DEPT.other }))
    expect((await call('admin', 'get', `/${mine.id}`).expect(200)).body.data).toEqual(mine)
  })
})

/** A binary (xlsx) response body as a Buffer. */
const binary = (r: request.Response, cb: (err: Error | null, body: Buffer) => void) => {
  const chunks: Buffer[] = []
  r.on('data', (c: Buffer) => chunks.push(c))
  r.on('end', () => cb(null, Buffer.concat(chunks)))
}
/** The first sheet of an xlsx body (or none). */
async function sheet(body: unknown) {
  const wb = new ExcelJS.Workbook()
  await wb.xlsx.load(body as Parameters<typeof wb.xlsx.load>[0])
  return wb.worksheets[0]
}
const cells = (ws: ExcelJS.Worksheet, row: number, length: number) =>
  Array.from({ length }, (_, i) => ws.getRow(row).getCell(i + 1).value ?? null)

describe('export', () => {
  /** GET /export as the parsed first sheet, with the response. */
  async function exported(who: keyof typeof tokens, query: object, headers: object = {}) {
    const res = await call(who, 'get', '/export')
      .query(query)
      .set(headers as Record<string, string>)
      .buffer(true)
      .parse(binary)
    return { res, ws: res.status === 200 ? await sheet(res.body) : undefined }
  }
  const row = (ws: ExcelJS.Worksheet, n: number) => cells(ws, n, HEADERS.length)

  it('export: every row (no paging) in list order as .xlsx, headers translated, formulas escaped, times in the zone', async () => {
    const tag = unique()
    await add(body(`${tag}-a`, { enabled: false }))
    const { id } = await add(body(`${tag}-b`, { title: '=1+1' }))
    // counted before: an export of the action log adds its own row right after
    const rows = await count()
    const { res, ws } = await exported('admin', { sort: '-id', pageSize: 1 })
    expect(res.status).toBe(200)
    expect(res.headers['content-type']).toContain('spreadsheetml.sheet')
    expect(res.headers['content-disposition']).toBe('attachment; filename="books.xlsx"')
    expect(row(ws!, 1)).toEqual(HEADERS.map((k) => t('zh-CN', k)))
    // all live rows, newest first; `=…` gets a `'` prefix
    expect(ws!.actualRowCount).toBe(rows + 1)
    expect(row(ws!, 2)[0]).toBe(`${tag}-b`)
    expect(row(ws!, 3)[0]).toBe(`${tag}-a`)
    expect(row(ws!, 2)[1]).toBe("'=1+1")
    // a dict column as its label
    expect(row(ws!, 3)[7]).toBe(await dictLabel('core.enabled', 'false'))
    // created_at (UTC) in core.default_timezone (Asia/Shanghai, +8h) unless X-Timezone says otherwise
    const [{ at }] = await ds.query('SELECT created_at AS at FROM demo_book WHERE id = ?', [id])
    const local = (d: Date, hours: number) =>
      new Date(d.getTime() + hours * 3600_000).toISOString().slice(0, 19).replace('T', ' ')
    expect(row(ws!, 2)[8]).toBe(local(at, 8))
    const utc = await exported('admin', { sort: '-id' }, { 'X-Timezone': 'UTC' })
    expect(row(utc.ws!, 2)[8]).toBe(local(at, 0))
  })

  it('export: English headers and labels for an en-US request', async () => {
    await add(body(unique()))
    const { ws } = await exported('admin', { sort: '-id' }, { 'Accept-Language': 'en-US' })
    expect(row(ws!, 1)).toEqual(HEADERS.map((k) => t('en-US', k)))
    expect(row(ws!, 2)[7]).toBe(await dictLabel('core.enabled', 'true', 'en-US'))
  })

  it('export: 403 without demo.book.export, 400 for a bad query, action-logged', async () => {
    expect((await exported('reader', {})).res.status).toBe(403)
    expect((await exported('admin', { sort: 'coverUrl' })).res.status).toBe(400)
    const traceId = `${PREFIX}${process.pid}-export`
    await exported('admin', { isbn: unique() }, { 'X-Request-Id': traceId })
    expect(await logOf(ds, traceId)).toMatchObject({ domain: 'demo.book', verb: 'export', ok: 1 })
  })
})

describe('import', () => {
  /** An .xlsx with the import headers (zh-CN labels) and `rows` (cells by field). */
  async function xlsx(rows: Record<string, unknown>[]) {
    const wb = new ExcelJS.Workbook()
    const ws = wb.addWorksheet('import')
    ws.addRow(IMPORT.map(([, key]) => t('zh-CN', key)))
    for (const r of rows) ws.addRow(IMPORT.map(([field]) => r[field] ?? null))
    return Buffer.from(await wb.xlsx.writeBuffer())
  }
  const upload = (who: keyof typeof tokens, file: Buffer, mode = 'insert', traceId = unique()) =>
    request(app.getHttpServer())
      .post(`${URL}/import`)
      .set(bearer(tokens[who]))
      .set('X-Request-Id', traceId)
      .field('mode', mode)
      .attach('file', file, 'import.xlsx')
  /** The newest row of the list. */
  const newest = async () =>
    (await call('admin', 'get').query({ sort: '-id', pageSize: 1 }).expect(200)).body.data.items

  it('import template: the importable columns as translated headers', async () => {
    const res = await call('admin', 'get', '/import-template')
      .buffer(true)
      .parse(binary)
      .expect(200)
    expect(res.headers['content-disposition']).toBe('attachment; filename="books.xlsx"')
    expect(cells((await sheet(res.body))!, 1, IMPORT.length)).toEqual(
      IMPORT.map(([, key]) => t('zh-CN', key)),
    )
  })

  it('import: valid rows are inserted, failed ones reported; upsert updates by isbn', async () => {
    const tag = unique()
    const res = await upload(
      'admin',
      await xlsx([body(`${tag}-a`), body(`${tag}-b`, { isbn: '' })]),
    ).expect(200)
    expect(res.body.data).toMatchObject({
      inserted: 1,
      updated: 0,
      failed: 1,
      reportId: expect.any(String),
    })
    expect(await newest()).toMatchObject([body(`${tag}-a`)])
    const again = { ...body(`${tag}-a`), title: `${tag} imported` }
    const up = await upload('admin', await xlsx([again]), 'upsert').expect(200)
    expect(up.body.data).toMatchObject({ inserted: 0, updated: 1, failed: 0 })
    expect(await newest()).toMatchObject([again])
  })

  it('import upsert matches only rows in the data scope: a isbn of another dept fails, nothing overwritten', async () => {
    const tag = unique()
    const other = await addIn(DEPT.other, tag)
    const res = await upload(
      'own',
      await xlsx([body(tag, { deptId: DEPT.mine })]),
      'upsert',
    ).expect(200)
    expect(res.body.data).toMatchObject({ inserted: 0, updated: 0, failed: 1 })
    expect((await call('admin', 'get', `/${other.id}`).expect(200)).body.data).toEqual(other)
  })

  it('import: 403 without demo.book.import, action-logged', async () => {
    const file = await xlsx([body(unique())])
    await upload('reader', file).expect(403)
    const traceId = `${PREFIX}${process.pid}-import`
    await upload('admin', file, 'insert', traceId).expect(200)
    expect(await logOf(ds, traceId)).toMatchObject({ domain: 'demo.book', verb: 'import', ok: 1 })
  })
})

it('@ActionLog: every write leaves a row with domain demo.book, its verb and the id', async () => {
  const trace = `${PREFIX}${process.pid}-`
  const created = await create(body(unique())).set('X-Request-Id', `${trace}c`).expect(201)
  const { id } = created.body.data
  await call('admin', 'put', `/${id}`, {}).set('X-Request-Id', `${trace}u`)
  await call('admin', 'put', `/${id}/enabled`, { enabled: false }).set('X-Request-Id', `${trace}e`)
  await call('admin', 'delete', `/${id}`).set('X-Request-Id', `${trace}d`)
  await call('admin', 'post', '/batch-delete', { ids: [MISSING] }).set('X-Request-Id', `${trace}b`)
  const expected: [string, object][] = [
    ['c', { verb: 'create', biz_id: String(id), ok: 1 }],
    ['u', { verb: 'modify', biz_id: String(id), ok: 1 }],
    ['e', { verb: 'modify', biz_id: String(id), ok: 1 }],
    ['d', { verb: 'remove', biz_id: String(id), ok: 1 }],
    ['b', { verb: 'remove', biz_id: null, ok: 0, error_msg: Err.NOT_FOUND.key }],
  ]
  for (const [suffix, row] of expected)
    expect(await logOf(ds, `${trace}${suffix}`)).toMatchObject({
      domain: 'demo.book',
      username: 'admin',
      ...row,
    })
})

it('Swagger documents every route', async () => {
  const doc = (await request(app.getHttpServer()).get('/api/docs-json').expect(200)).body
  expect(
    Object.keys(doc.paths)
      .filter((p) => p.startsWith(URL))
      .sort(),
  ).toEqual([
    URL,
    `${URL}/batch-delete`,
    `${URL}/export`,
    `${URL}/import`,
    `${URL}/import-template`,
    `${URL}/{id}`,
    `${URL}/{id}/enabled`,
  ])
  expect(
    doc.paths[URL].get.responses['200'].content['application/json'].schema.properties.data,
  ).toMatchObject({ properties: { items: { type: 'array' }, total: { type: 'integer' } } })
  // the configured examples
  expect(
    doc.paths[URL].post.requestBody.content['application/json'].schema.properties,
  ).toMatchObject({
    publishedOn: { example: '2024-05-01' },
    price: { example: 42.5 },
    genre: { example: 'fiction' },
  })
})
